SourceCode.Declaration:
class METSalesOrderExtractionPendingProcess
{
    SalesUpdateRemain   salesUpdateRemain;
    int                 batchTransactionCommit;
    int                 totalCancelledLineCount;
}

Method.Source:
public static METSalesOrderExtractionPendingProcess construct()
{
    METSalesOrderExtractionPendingProcess instance = new METSalesOrderExtractionPendingProcess();
    instance.batchTransactionCommit = METCustParameters::find().SalesExtractionBatchTransactionCommit;
    return instance;
}

public void processRecord(METOrderExtractionPendingProcess _pendingRecord)
{
    METOrderExtractionPendingProcess pendingRecordUpd;
    boolean                          skipRecord    = false;
    boolean                          isError       = false;

    // Optimistic locking — claim the record for processing
    ttsbegin;
    select forupdate pendingRecordUpd
        where pendingRecordUpd.RecId == _pendingRecord.RecId;

    if (pendingRecordUpd.RecVersion == _pendingRecord.RecVersion)
    {
        if (pendingRecordUpd.Status == METOrderExtractionPendingProcessStatus::Pending  ||
            pendingRecordUpd.Status == METOrderExtractionPendingProcessStatus::Failed)
        {
            xSession xSession = new xSession(sessionid());
            pendingRecordUpd.Status               = METOrderExtractionPendingProcessStatus::Processing;
            pendingRecordUpd.ProcessStartDateTime = DateTimeUtil::getSystemDateTime();
            pendingRecordUpd.SessionId            = xSession.sessionId();
            pendingRecordUpd.SessionLoginDateTime = xSession.loginDateTime();
            pendingRecordUpd.update();
        }
        else
        {
            skipRecord = true;
        }
    }
    else
    {
        skipRecord = true;
    }
    ttscommit;

    if (skipRecord)
    {
        return;
    }

    try
    {
        this.processSalesOrder(_pendingRecord.SalesId, _pendingRecord.PickingRouteID, _pendingRecord.ActionToPerform);

        ttsbegin;
        select forupdate pendingRecordUpd
            where pendingRecordUpd.RecId == _pendingRecord.RecId;
        pendingRecordUpd.Status                      = METOrderExtractionPendingProcessStatus::Completed;
        pendingRecordUpd.ProcessEndDateTime          = DateTimeUtil::getSystemDateTime();
        pendingRecordUpd.TotalCancelledLineCount     = totalCancelledLineCount;
        pendingRecordUpd.update();
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        isError = true;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            isError = true;
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::UpdateConflictNotRecovered)
    {
        isError = true;
    }
    catch (Exception::Error)
    {
        isError = true;
    }
    catch
    {
        isError = true;
    }

    if (isError)
    {
        ttsbegin;
        select forupdate pendingRecordUpd
            where pendingRecordUpd.RecId == _pendingRecord.RecId;
        pendingRecordUpd.Status             = METOrderExtractionPendingProcessStatus::Failed;
        pendingRecordUpd.RetryCount++;
        pendingRecordUpd.ProcessEndDateTime = DateTimeUtil::getSystemDateTime();
        pendingRecordUpd.update();
        ttscommit;
    }
}

/// <summary>
/// Branches by ActionToPerform. SOExtractCreateOnlyTO only creates the transfer order.
/// SOExtractReservedSOPickAndTO/SOExtractOrderedSOPickOnly/SOExtractReservedSOPickOnly run
/// the standard pipeline plus the intercompany leg's pick list; the first also creates the
/// transfer order. Everything else just runs the standard pipeline.
/// </summary>
/// <param name = "_salesId">Sales order to process</param>
/// <param name = "_pickingRouteId">Picking route id, if any</param>
/// <param name = "_actionToPerform">Action code stamped during extraction</param>
private void processSalesOrder(SalesId _salesId, WMSPickingRouteID _pickingRouteId = '', str _actionToPerform = '')
{
    // Fresh SalesUpdateRemain per SalesId - resets orderCheckUpdateDone cache
    salesUpdateRemain        = null;
    totalCancelledLineCount  = 0;

    SalesTable salesTable = SalesTable::find(_salesId);

    if (!salesTable.RecId)
    {
        return;
    }

    METSalesTable metSalesTable = METSalesTable::findBySalesTable(salesTable.RecId);

    switch (_actionToPerform)
    {
        case METConstants::SOExtractCreateOnlyTO:
            this.processCrossDockTransferOrder(salesTable);
            break;

        case METConstants::SOExtractReservedSOPickAndTO:
            this.processStandardPipeline(salesTable, metSalesTable, _pickingRouteId);
            this.processIntercompanyPickingList(salesTable);
            this.processCrossDockTransferOrder(salesTable);
            break;

        case METConstants::SOExtractOrderedSOPickOnly:
        case METConstants::SOExtractReservedSOPickOnly:
            this.processStandardPipeline(salesTable, metSalesTable, _pickingRouteId);
            this.processIntercompanyPickingList(salesTable);
            break;

        default:
            this.processStandardPipeline(salesTable, metSalesTable, _pickingRouteId);
            break;
    }

    info(strFmt("@MET:METExtractionPendingProcessCompleted", _salesId));
}

// Full cancellation: lines with no WMS order created (zero reserved stock)
private void cancelZeroStockLines(SalesTable _salesTable)
{
    SalesLine    salesLine;
    METSalesLine metSalesLine;
    WMSOrder     wmsOrder;
    boolean      batchOpen   = false;
    int          batchCount  = 0;
    int          cancelCount = 0;

    while select forupdate salesLine
        where salesLine.SalesId          == _salesTable.SalesId
           && salesLine.SalesStatus      != SalesStatus::Canceled
           && salesLine.InventRefType    != InventRefType::Purch
           && salesLine.RemainSalesPhysical > 0
        join metSalesLine
            where metSalesLine.SalesLine          == salesLine.RecId
               && metSalesLine.OrderExtractStatus == METOrderExtractStatus::Extracted
        notexists join wmsOrder
            where wmsOrder.inventTransId == salesLine.InventTransId
               && wmsOrder.type          == WMSOrderType::OrderPick
    {
        if (!batchOpen)
        {
            ttsbegin;
            batchOpen = true;
        }

        if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
        {
            this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
        }
        else
        {
            this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0);
        }

        info(strFmt("@MET:METNoStockPendingProcess", salesLine.SalesId, salesLine.ItemId));

        totalCancelledLineCount++;
        cancelCount++;
        batchCount++;
        if (batchCount >= batchTransactionCommit)
        {
            ttscommit;
            batchOpen  = false;
            batchCount = 0;
        }
    }

    if (batchOpen)
    {
        ttscommit;
    }

    info(strFmt("@MET:METZeroStockCancellationCompleted", _salesTable.SalesId, cancelCount));
}

// Partial cancellation: lines where cumulative WMS shipped qty is less than remaining inventory qty
private void cancelShortPickLines(SalesTable _salesTable)
{
    SalesLine    salesLine;
    METSalesLine metSalesLine;
    WMSOrder     wmsOrder;
    boolean      batchOpen   = false;
    int          batchCount  = 0;
    int          cancelCount = 0;

    while select forupdate salesLine
        where salesLine.SalesId              == _salesTable.SalesId
           && salesLine.SalesStatus          != SalesStatus::Canceled
           && salesLine.InventRefType        != InventRefType::Purch
           && salesLine.RemainInventPhysical  > 0
        join metSalesLine
            where metSalesLine.SalesLine          == salesLine.RecId
               && metSalesLine.OrderExtractStatus == METOrderExtractStatus::Extracted
        exists join wmsOrder
            where wmsOrder.inventTransId == salesLine.InventTransId
               && wmsOrder.type          == WMSOrderType::OrderPick
    {
        // Sum across all pick lines for this salesLine (split picklist registrations)
        WMSOrder wmsOrderSum;
        select sum(qty), sum(qtyNoShipment), sum(PdsCWQty), sum(PdsCWQtyNoShipment)
            from wmsOrderSum
            where wmsOrderSum.inventTransId == salesLine.InventTransId
               && wmsOrderSum.type          == WMSOrderType::OrderPick;

        InventQty      shipQty   = abs(wmsOrderSum.qty) - wmsOrderSum.qtyNoShipment;
        PdsCWInventQty cwShipQty = PdsGlobal::pdsIsCWItem(salesLine.ItemId)
                                    ? abs(wmsOrderSum.PdsCWQty) - wmsOrderSum.PdsCWQtyNoShipment
                                    : 0;

        if (shipQty < salesLine.RemainInventPhysical)
        {
            InventQty shipQtySales = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                salesLine.ItemId,
                salesLine.InventDimId,
                shipQty,
                salesLine.inventTable().inventUnitId(),
                salesLine.SalesUnit,
                NoYes::No,
                NoYes::No);

            if (!batchOpen)
            {
                ttsbegin;
                batchOpen = true;
            }

            salesLine.skipBusinessEvents(true);

            this.salesUpdateRemain().updateExtractionDeliverRemainder(
                salesLine,
                shipQtySales,
                shipQty,
                cwShipQty);

            totalCancelledLineCount++;
            cancelCount++;
            batchCount++;
            if (batchCount >= batchTransactionCommit)
            {
                ttscommit;
                batchOpen  = false;
                batchCount = 0;
            }
        }
    }

    if (batchOpen)
    {
        ttscommit;
    }

    info(strFmt("@MET:METShortPickCancellationCompleted", _salesTable.SalesId, cancelCount));
}

private void updateSalesTableStatus(SalesTable _salesTable)
{
    SalesTable salesTableUpd;

    ttsbegin;
    salesTableUpd = SalesTable::find(_salesTable.SalesId, true);
    salesTableUpd.updateBackStatus();
    salesTableUpd.updateSalesType();
    ttscommit;

    info(strFmt("@MET:METSalesTableStatusUpdateCompleted", _salesTable.SalesId));
}

private void processTMSOrder(WMSPickingRouteID _pickingRouteId, SalesTable _salesTable)
{
    if (!_pickingRouteId)
    {
        return;
    }

    _salesTable.reread();

    WMSPickingRoute wmsPickingRoute = WMSPickingRoute::find(_pickingRouteId);

    if (wmsPickingRoute.RecId
        && _salesTable.METOrderExtractStatus == METOrderExtractStatus::Extracted
        && _salesTable.SalesStatus           != SalesStatus::Delivered
        && _salesTable.SalesStatus           != SalesStatus::Invoiced)
    {
        // TMS manages its own transaction; run outside any tts scope
        METTMSEngineOrderProccess metTMSEngineOrderProccess = METTMSEngineOrderProccess::construct(
            METTMSEngineExecutionMode::SalesOrderPickingList,
            wmsPickingRoute,
            _pickingRouteId);
        metTMSEngineOrderProccess.run();

        info(strFmt("@MET:METTMSEngineOrderProcessCompleted", _salesTable.SalesId));
    }
}

// Runs for SOExtractReservedSOPickAndTO and SOExtractCreateOnlyTO. CreateTransferOrder manages its own tts + internal TMS.
private void processCrossDockTransferOrder(SalesTable _salesTable)
{
    _salesTable.reread();
    METCrossDockTransferOrderProcessorBase::construct(_salesTable).CreateTransferOrder();

    info(strFmt("@MET:METCrossDockTOProcessCompleted", _salesTable.SalesId));
}

// Mirrors reservation + pick list posting onto the intercompany purchase order's sales side, in its own company.
private void processIntercompanyPickingList(SalesTable _salesTable)
{
    PurchTable purchTable_Reference = _salesTable.referencePurchTable();

    if (!purchTable_Reference.RecId || !TradeInterCompany::checkDataAreaAccess(purchTable_Reference.InterCompanyCompanyId))
    {
        return;
    }

    changeCompany(purchTable_Reference.InterCompanyCompanyId)
    {
        SalesTable interCompanySalesTable = purchTable_Reference.interCompanySalesTable();

        METStockReservation::construct(interCompanySalesTable).processV2();
        METSalesPickingListFulfillmentBatch salesPickingListFulFillmentBatch = new METSalesPickingListFulfillmentBatch();
        salesPickingListFulFillmentBatch.postIntercompanySalesTablePickList(interCompanySalesTable);
    }

    info(strFmt("@MET:METIntercompanyPickingListPendingProcessCompleted", _salesTable.SalesId));
}

private SalesUpdateRemain salesUpdateRemain()
{
    if (salesUpdateRemain == null)
    {
        salesUpdateRemain = SalesUpdateRemain::construct();
        salesUpdateRemain.metParmIsExtraction(true);
    }
    return salesUpdateRemain;
}

/// <summary>
/// Cancel zero-stock/short-pick lines (unless back orders are allowed or this is an
/// internal cross-dock order), then update SO status and trigger the TMS order.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_metSalesTable">Metcash sales order extension</param>
/// <param name = "_pickingRouteId">Picking route id, if any</param>
private void processStandardPipeline(SalesTable _salesTable, METSalesTable _metSalesTable, WMSPickingRouteID _pickingRouteId)
{
    if (!_salesTable.METAllowBackOrders && !_metSalesTable.InternalCrossDockOrder)
    {
        this.cancelZeroStockLines(_salesTable);
        salesUpdateRemain = null;
        this.cancelShortPickLines(_salesTable);
    }

    this.updateSalesTableStatus(_salesTable);
    this.processTMSOrder(_pickingRouteId, _salesTable);
}
